let selectedToken = canvas.tokens.controlled[0];
if (!selectedToken) {
    ui.notifications.warn("未选中拓可！");
    return;
}

const itemUUID = "Compendium.dnd5e-collection-2024.phb-content.Item.BPQglJjmgXc96UIf";

let item = await fromUuid(itemUUID);
if (!item) {
    ui.notifications.error("效应库丢失！");
    return;
}

const effectName = "疾走";
let effect = item.effects.find(e => e.name === effectName);

if (!effect) {
    ui.notifications.error("效应丢失！");
    return;
}

const duration = effect.duration.seconds ? effect.duration.seconds : 0; // 确保其有持续时间

await selectedToken.actor.createEmbeddedDocuments("ActiveEffect", [{
    name: effect.name,
    img: effect.img,
    duration: {
        seconds: duration,
        rounds: null,
        turns: null,
        startTime: null,
        combat: null
    },
    changes: effect.changes,
    ...effect.system
}]);


let Action = `
    <div class="message-content">
        <div class="dnd5e2 chat-card activation-card" data-display-challenge="">
            <section class="card-header description collapsible">
                <header class="summary">
                    <img class="gold-icon" src="modules/dnd5e-collection-2024/assets/icons/abilities/ACTION_dash.webp">
                    <div class="name-stacked border">
                        <span class="title">疾走</span>
                        <span class="subtitle">动作</span>
                    </div>
                    <i class="fa-solid fa-chevron-down fa-fw" inert=""></i>
                </header>
                <section class="details collapsible-content card-content">
                    <div class="wrapper">
                        @Embed[Compendium.dnd5e-collection-2024.players-handbook.JournalEntry.JaBtNuiFJZaRoJWX.JournalEntryPage.6l6nBKip4LqB1sCU inline]
                    </div>
                </section>
            </section>
        </div>
    </div>
`;

ChatMessage.create({
    speaker: ChatMessage.getSpeaker({token: actor}),
    content: Action
});
